import {
  ConnectedSocket,
  MessageBody,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from "@nestjs/websockets"
import { Server, Socket } from "socket.io"

interface ChatMessageDto {
  username: string
  room: string
  text: string
}

interface JoinRoomDto {
  room: string
}

@WebSocketGateway({ cors: true })
export class ChatGateway {
  @WebSocketServer()
  server: Server

  // Handshake middleware (wired in the gateway's `afterInit`, not shown here)
  // already verified the JWT once at connection time and attached the
  // authenticated identity to the socket:
  //   client.data.user = { id: payload.sub, username: payload.username }
  // Every socket reaching the handlers below is already authenticated.

  @SubscribeMessage("room:join")
  handleJoin(
    @ConnectedSocket() client: Socket,
    @MessageBody() body: JoinRoomDto,
  ): void {
    client.join(body.room)
  }

  @SubscribeMessage("chat:message")
  handleMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() body: ChatMessageDto,
  ): void {
    const { username, room, text } = body

    this.server.to(room).emit("chat:message", {
      username,
      text,
    })
  }
}
